import java.io.*; import java.util.*; import javax.xml.parsers.*; import org.w3c.dom.*; import org.netbeans.modules.form.layoutdesign.*;
public class VerifyNetBeansLayout {
 static Element child(Element e,String tag) { for(Node n=e.getFirstChild();n!=null;n=n.getNextSibling()) if(n instanceof Element x && x.getTagName().equals(tag)) return x; return null; }
 static String shape(Element e) { StringBuilder b=new StringBuilder(e.getTagName()); if(e.hasAttribute("type") && e.getTagName().equals("Group")) b.append(':').append(e.getAttribute("type")); if(e.hasAttribute("id")) b.append(':').append(e.getAttribute("id")); b.append('['); for(Node n=e.getFirstChild();n!=null;n=n.getNextSibling()) if(n instanceof Element x) b.append(shape(x)); return b.append(']').toString(); }
 static void verify(Element container,String id) throws Exception { Element layout=child(container,"Layout"); if(layout!=null && !layout.hasAttribute("class")) { Map<String,String> names=new HashMap<>(); Element children=child(container,"SubComponents"); if(children!=null) for(Node n=children.getFirstChild();n!=null;n=n.getNextSibling()) if(n instanceof Element x) names.put(x.getAttribute("name"),x.getAttribute("name")); LayoutModel m=new LayoutModel(); m.loadContainerLayout(id,layout.getChildNodes(),names); String saved=m.saveContainerLayout(m.getLayoutComponent(id),names,0,false); Element restored=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new ByteArrayInputStream(("<Layout>"+saved+"</Layout>").getBytes(java.nio.charset.StandardCharsets.UTF_8))).getDocumentElement(); if(!shape(layout).equals(shape(restored))) throw new AssertionError(id+": NetBeans changes layout hierarchy when loading this form.\nExpected: "+shape(layout)+"\nLoaded: "+shape(restored)); System.out.println(id+": native NetBeans parser round-trip preserves layout"); } Element subs=child(container,"SubComponents"); if(subs!=null) for(Node n=subs.getFirstChild();n!=null;n=n.getNextSibling()) if(n instanceof Element x && x.getTagName().equals("Container")) verify(x,x.getAttribute("name")); }
 public static void main(String[] args) throws Exception { for(String path:args) { Element root=DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new File(path)).getDocumentElement(); verify(root,"Form"); System.out.println(path+": PASS"); } }
}
